// TypeScript Orchestration: Enterprise Customer Vitality Matrix & CRM Activation Engine
interface CustomerBTYDProfile {
  customerId: string;
  pAlive: number;           // Probability of being alive (0.0 to 1.0)
  expectedOrdersNextYear: number;
  expectedAOV: number;       // Bayesian shrunk AOV in USD
  predicted12MoCLV: number;  // Forward 12-month discounted CLV
}

interface StrategicCohortAction {
  cohortName: 'CORE_CHAMPIONS' | 'AT_RISK_WHALES' | 'LAPSED_WHALES' | 'STEADY_LOYALS' | 'SUPPRESSED_DEFECTED';
  crmJourney: string;
  adSuppressionStatus: boolean;
  biddingMultiplier: number;
  suggestedIncentive: string;
}

class EnterpriseCustomerEquityOrchestrator {
  private clvHighThreshold = 500.0; // High value customer cutoff in USD

  public classifyAndRouteCustomer(profile: CustomerBTYDProfile): StrategicCohortAction {
    const isHighValue = profile.predicted12MoCLV >= this.clvHighThreshold;

    // 1. Core Champions: High Alive & High Value
    if (profile.pAlive >= 0.75 && isHighValue) {
      return {
        cohortName: 'CORE_CHAMPIONS',
        crmJourney: 'VIP_CONCIERGE_AND_EXCLUSIVE_PREVIEWS',
        adSuppressionStatus: false,
        biddingMultiplier: 3.5, // Aggressive programmatic lookalike seed
        suggestedIncentive: 'Zero discount; invite to private flagship tasting'
      };
    }

    // 2. At-Risk Whales: Moderate Alive & High Value
    if (profile.pAlive >= 0.30 && profile.pAlive < 0.75 && isHighValue) {
      return {
        cohortName: 'AT_RISK_WHALES',
        crmJourney: 'URGENT_DIRECTOR_OUTREACH_AND_GIFT',
        adSuppressionStatus: false,
        biddingMultiplier: 2.0,
        suggestedIncentive: 'Complimentary high-value gift with next purchase'
      };
    }

    // 3. Lapsed Whales: Low Alive & High Value
    if (profile.pAlive < 0.30 && isHighValue) {
      return {
        cohortName: 'LAPSED_WHALES',
        crmJourney: 'QUARTERLY_WIN_BACK_CAMPAIGN',
        adSuppressionStatus: true, // Suppress from daily digital retargeting to save ad spend
        biddingMultiplier: 0.5,
        suggestedIncentive: '$100 credit on orders over $300'
      };
    }

    // 4. Steady Loyals: High Alive & Moderate Value
    if (profile.pAlive >= 0.75 && !isHighValue) {
      return {
        cohortName: 'STEADY_LOYALS',
        crmJourney: 'CROSS_SELL_BASKET_EXPANSION',
        adSuppressionStatus: false,
        biddingMultiplier: 1.0,
        suggestedIncentive: 'Bundle discount: buy 2 get 1 free on adjacent categories'
      };
    }

    // 5. Suppressed Defected: Low Alive & Low Value
    return {
      cohortName: 'SUPPRESSED_DEFECTED',
      crmJourney: 'TOTAL_COMMUNICATION_SUPPRESSION',
      adSuppressionStatus: true,
      biddingMultiplier: 0.0, // Zero ad spend allocation
      suggestedIncentive: 'None; preserve marketing capital'
    };
  }
}

// Simulate customer base processing
const orchestrator = new EnterpriseCustomerEquityOrchestrator();

const testProfiles: CustomerBTYDProfile[] = [
  { customerId: 'CUST-001', pAlive: 0.92, expectedOrdersNextYear: 6.2, expectedAOV: 180.0, predicted12MoCLV: 1116.0 },
  { customerId: 'CUST-002', pAlive: 0.45, expectedOrdersNextYear: 2.1, expectedAOV: 320.0, predicted12MoCLV: 672.0 },
  { customerId: 'CUST-003', pAlive: 0.15, expectedOrdersNextYear: 0.4, expectedAOV: 450.0, predicted12MoCLV: 180.0 },
  { customerId: 'CUST-004', pAlive: 0.88, expectedOrdersNextYear: 4.0, expectedAOV: 45.0,  predicted12MoCLV: 180.0 },
  { customerId: 'CUST-005', pAlive: 0.08, expectedOrdersNextYear: 0.1, expectedAOV: 50.0,  predicted12MoCLV: 5.0 }
];

console.log('=== ENTERPRISE CUSTOMER EQUITY ACTIVATION MATRIX ===\n');
testProfiles.forEach(p => {
  const action = orchestrator.classifyAndRouteCustomer(p);
  console.log(`Customer: ${p.customerId} | P(Alive): ${(p.pAlive * 100).toFixed(0)}% | 12Mo CLV: $${p.predicted12MoCLV.toFixed(2)}`);
  console.log(`  -> Cohort: ${action.cohortName}`);
  console.log(`  -> CRM Routing: ${action.crmJourney}`);
  console.log(`  -> Ad Suppression: ${action.adSuppressionStatus} | Bid Multiplier: ${action.biddingMultiplier}x`);
  console.log(`  -> Policy: ${action.suggestedIncentive}\n`);
});
